result:
**The bug:** The condition `decoded.exp < Date.now() / 1000` uses strict less-than, so a token whose `exp` equals the current Unix timestamp (expired at exactly "now") passes through. It should be `<=`.

**Secondary issue:** `jwt.verify()` already validates expiry and throws `TokenExpiredError` — the manual check is redundant. If both exist, they can diverge. Better to rely on the library and handle its specific error types.

Here's the fixed version:

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'No token provided' });
  }

  const token = authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    // jwt.verify rejects tokens where exp <= now (i.e. exp at current second is treated as expired)
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    if (err.name === 'NotBeforeError') {
      return res.status(401).json({ error: 'Token not yet valid' });
    }
    // Unexpected errors (e.g. missing JWT_SECRET) should not leak details
    console.error('Auth middleware error:', err);
    return res.status(500).json({ error: 'Authentication error' });
  }
}

module.exports = authMiddleware;
```

**Summary of changes:**

| Issue | Before | After |
|---|---|---|
| Boundary bug | `exp < now` (accepts expired-at-now tokens) | Removed — `jwt.verify` uses `exp <= now`, correctly rejecting them |
| Redundant manual check | Manual `exp` comparison after `jwt.verify` | Removed; library handles it authoritatively |
| Error specificity | All errors → same generic message | `TokenExpiredError`, `JsonWebTokenError`, `NotBeforeError` handled separately |
| Unexpected errors | Silently returns 401 | Logged server-side, returns 500 without leaking internals |
| Header validation | Only checks token presence | Also validates `Bearer` scheme before splitting |
